const body = $json.body ?? $json;
const transcript = body.transcript;
const tx = body.transaction;
const errors = [];
if (typeof transcript !== 'string' || transcript.trim().length === 0) errors.push('transcript is required');
if (!tx || typeof tx !== 'object' || Array.isArray(tx)) errors.push('transaction object is required');
const allowed = ['donation_received','purchase_received','reimbursement_requested','inventory_used','inventory_adjustment','cash_contribution','equipment_received'];
if (tx && !allowed.includes(tx.transaction_type)) errors.push('transaction_type is missing or invalid');
if (tx && (!Array.isArray(tx.items) || tx.items.length === 0)) errors.push('at least one item is required');
if (tx && tx.items && Array.isArray(tx.items)) {
  tx.items.forEach((item, i) => {
    if (!item || typeof item !== 'object') errors.push('items[' + i + '] must be an object');
    else {
      if (!item.description) errors.push('items[' + i + '].description is required');
      if (item.quantity === null || item.quantity === undefined || typeof item.quantity !== 'number' || item.quantity < 0) errors.push('items[' + i + '].quantity must be a non-negative number');
      if (!item.unit) errors.push('items[' + i + '].unit is required');
    }
  });
}
if (tx && tx.amount_paid !== null && tx.amount_paid !== undefined && (typeof tx.amount_paid !== 'number' || tx.amount_paid < 0)) errors.push('amount_paid must be a non-negative number or null');
const sourceId = body.source_message_id ?? body.sourceMessageId ?? null;
return [{ json: { ok: errors.length === 0, status: errors.length === 0 ? 'draft_needs_approval' : 'needs_correction', source_message_id: sourceId, transcript: typeof transcript === 'string' ? transcript : null, transaction: tx ?? null, errors, received_at: new Date().toISOString(), warning: 'Validation only. No official record has been saved or approved.' } }];
